// 创建一个任务对象，该任务立即进入 pending 状态
const task = new Promise((resolve, reject) => {
  // 任务的具体执行流程，该函数会立即被执行
  // 调用 resolve(data)，可将任务变为 fullfilled 状态，data 为需要传递的相关数据
  // 调用 reject(reason)，可将任务变为 rejected 状态，reason 为需要传递的失败原因
});

task.then(
  (data) => {
    // onFullfilled 函数，当任务完成后，会自动执行该函数，data 为任务完成的相关数据
  },
  (reason) => {
    // onRejected 函数，当任务失败后，会自动执行该函数，reason 为任务失败的相关原因
  }
);

