// 策略接口
interface PaymentStrategy {
  pay(amount: number): void;
}

// 具体策略类 - 信用卡支付
class CreditCardPayment implements PaymentStrategy {
  private name: string;
  private cardNumber: string;

  constructor(name: string, cardNumber: string) {
    this.name = name;
    this.cardNumber = cardNumber;
  }

  pay(amount: number): void {
    console.log(`Paid $${amount} with credit card (${this.cardNumber})`);
  }
}

// 具体策略类 - PayPal支付
class PayPalPayment implements PaymentStrategy {
  private email: string;

  constructor(email: string) {
    this.email = email;
  }

  pay(amount: number): void {
    console.log(`Paid $${amount} with PayPal (${this.email})`);
  }
}

// 具体策略类 - 加密货币支付
class CryptoPayment implements PaymentStrategy {
  private walletAddress: string;

  constructor(walletAddress: string) {
    this.walletAddress = walletAddress;
  }

  pay(amount: number): void {
    console.log(`Paid $${amount} with cryptocurrency (${this.walletAddress})`);
  }
}

// 上下文类
class PaymentContext {
  private strategy: PaymentStrategy;

  constructor(strategy: PaymentStrategy) {
    this.strategy = strategy;
  }

  // 设置策略（允许动态切换策略）
  setStrategy(strategy: PaymentStrategy) {
    this.strategy = strategy;
  }

  // 执行支付
  executePayment(amount: number): void {
    this.strategy.pay(amount);
  }
}

// 使用示例
const creditCard = new CreditCardPayment("John Doe", "1234-5678-9012-3456");
const paypal = new PayPalPayment("john@example.com");
const crypto = new CryptoPayment("1A2b3C4d5E6f7G8h9I0j");

const payment = new PaymentContext(creditCard);

// 使用信用卡支付
payment.executePayment(100); // Paid $100 with credit card (1234-5678-9012-3456)

// 切换到 PayPal 支付
payment.setStrategy(paypal);
payment.executePayment(50); // Paid $50 with PayPal (john@example.com)

// 切换到加密货币支付
payment.setStrategy(crypto);
payment.executePayment(200); // Paid $200 with cryptocurrency (1A2b3C4d5E6f7G8h9I0j)
